const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${icons[name]||icons.info}</svg>`;
const esc=(value)=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const backend={base:window.AIRBORDER_API_BASE ?? (['localhost','127.0.0.1'].includes(location.hostname) ? '' : 'https://airborder-figma-api-20261015.writeraravinda.workers.dev'),directory:[],directoryStatus:'loading',calculation:null,calculationKey:null};
const state={view:'journey',scenario:'connection',zone:'airside',filter:'all',plan:[],routeStep:0,routeActive:false,routeDirect:false,largeText:false,pace:'typical',minutesUntilClose:null,typicalWalk:12,accessible:false,bags:'through',returnView:'journey',showSources:false};
const J=AirBorderJourney;
let journeyState=J.create(), activeDriver=null, displayedRecommendations=[];
const presenterMode=new URLSearchParams(location.search).get('presenter')==='1';
if(!presenterMode){try{const stored=JSON.parse(sessionStorage.getItem('airborder-journey-v1'));if(stored&&Array.isArray(stored.stops)&&stored.stops.every(s=>J.catalog[s.facilityId]&&Number.isFinite(s.minutes))&&Number.isFinite(stored.revision)&&stored.observations&&Array.isArray(stored.transfers))journeyState=stored;}catch{}}

function selected(id){return journeyState.stops.some(x=>x.facilityId===id);}
const scenarioNames={connection:'Haneda · Scheduled',change:'Gate changed to 108A',urgent:'Return to your gate',late:'Boarding at risk',critical:'Boarding assistance',transfer:'Transfer HND → NRT',offline:'Offline · Loaded itinerary'};
const titles={journey:'Your journey',flights:'Flight details',explore:'Make time for yourself',map:'Find your way',guide:'One step at a time',settings:'Your preferences'};
const navNames={journey:'Journey',flights:'Flights',explore:'Layover & transit',map:'Terminal map',guide:'Route guide',settings:'Preferences'};
const facilities=[
 {id:'rest',name:'Quiet time near Gate 105',category:'rest',symbol:'rest',desc:'Take a seat in the departure area while keeping your onward gate close by.',duration:'45 min',walk:'4 min walk',zone:'Airside · Terminal 3'},
 {id:'coffee',name:'A coffee before boarding',category:'food',symbol:'coffee',desc:'Pick up a coffee on your way to the departure gate.',duration:'25 min',walk:'6 min walk',zone:'Airside · Terminal 3'},
 {id:'work',name:'A little time to focus',category:'work',symbol:'rest',desc:'Find a seat for a short work session. Outlet and seating availability need checking on arrival.',duration:'40 min',walk:'5 min walk',zone:'Airside · Terminal 3'}
];
function context(){
 const s=state.scenario,changed=s==='change',transfer=s==='transfer';
 const available=Math.max(0,journeyState.deadline-journeyState.now);
 const direct=J.estimate(journeyState,[]),walk=direct.travel;
 return {routeKnown:direct.known,urgent:!transfer&&direct.known&&(available<=25||available-walk<=10),changed,transfer,offline:s==='offline',gate:journeyState.gate,airport:transfer?'NRT':'HND',flight:transfer?'NH 6':'NH 106',available,walk};
}
function time(total){return total>=60?`${Math.floor(total/60)}h ${total%60}m`:`${total} min`;}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3500);document.querySelector('#announcement').textContent=message;}
function navigate(view){if(view==='guide'&&context().routeKnown&&!context().transfer&&!state.routeActive){state.routeStep=0;state.routeDirect=false;state.routeActive=true;}state.view=view;render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#main').focus({preventScroll:true});}
function resetScenario(value){state.scenario=value;state.minutesUntilClose=null;state.typicalWalk=12;journeyState.gate=value==='change'?'108A':'105';journeyState.dataRevision++;state.zone='airside';render();toast(({connection:'Showing your Haneda connection.',change:'Gate changed: 105 → 108A. Your route has been updated.',urgent:'Return to Gate 105. The gate closes in 25 minutes.',late:'Go directly to your gate. Ask airline staff for help if needed.',critical:'You may miss boarding. Contact the airline for assistance.',transfer:'Your next flight departs Narita. Review the airport-transfer steps.',offline:'You’re offline. Showing the itinerary loaded in this session.'})[value]);}
function pill(text,type='',symbol=''){return `<span class="pill ${type}">${symbol?icon(symbol):''}${text}</span>`;}
function navButton(v,mobile=false){const label=mobile?({journey:'Journey',flights:'Flights',explore:'Layover',map:'Map'}[v]||navNames[v]):navNames[v];return `<button type="button" data-view="${v}" class="${state.view===v?'active':''}" ${state.view===v?'aria-current="page"':''}>${icon(v)}<span>${label}</span></button>`;}
function shell(content){return `<div class="shell ${state.largeText?'large-text':''}">
 <aside class="sidebar" aria-label="AirBorder navigation"><div class="brand">${icon('plane')}AirBorder</div><div class="brand-sub">Plan your next connection</div><nav class="nav" aria-label="Main">${Object.keys(navNames).map(v=>navButton(v)).join('')}</nav><div class="sidebar-bottom"><span class="small-mark"></span>Your journey, together<br><span style="font-size:11px">Bangkok → Tokyo → Los Angeles</span><button data-action="about">About AirBorder ${icon('arrow')}</button></div></aside>
 <div class="workspace"><header class="topbar"><div class="mobile-brand">${icon('plane')}AirBorder</div><div class="crumb">${icon('journey')}<strong>Your connection</strong><span>/</span><span>Tokyo, Japan</span></div><div class="top-controls"><button class="icon-button" data-view="settings" aria-label="Preferences">${icon('settings')}</button><button class="avatar" data-action="profile" aria-label="AV, traveler profile">AV</button></div></header>
 <main id="main" class="body" tabindex="-1"><div class="page-heading"><div><div class="eyebrow">${state.view==='journey'?'A little clarity goes a long way':navNames[state.view]}</div><h1>${titles[state.view]}</h1><p class="sub">${subtitle()}</p></div>${pill('15 OCT · TOKYO','neutral')}</div><p class="demo-disclosure">Demo journey: Flight, timing and route information are simulated. The airport directory uses published airport information.</p>${globalUpdate()}${content}<footer class="note-footer"><span>AirBorder · A calmer way through your connection.</span><button data-action="about">Help & information</button></footer></main></div>
 <nav class="bottom-nav" aria-label="Mobile navigation">${['journey','flights','explore','map'].map(v=>navButton(v,true)).join('')}<button data-action="more" class="${['guide','settings'].includes(state.view)?'active':''}" aria-label="More: route guide and preferences">${icon('more')}<span>More</span></button></nav></div>`;}
function subtitle(){return {journey:'Your Haneda connection, gate details, and next steps.',flights:'Your itinerary, local times, and onward departure in one place.',explore:'Find places to rest, eat, or work between flights.',map:'Review the terminal route and directions to your gate.',guide:'Your onward gate, one clear direction at a time.',settings:'Shape the experience around the way you travel.'}[state.view];}
function offlineNotice(){return context().offline?`<section class="travel-update offline" role="status" aria-label="Connection update"><div class="update-icon">${icon('offline')}</div><div><div class="update-label">CONNECTION STATUS</div><h2>You’re offline</h2><p>Showing the itinerary loaded in this session. Gate and boarding information may have changed.</p><div class="update-next"><strong>Next step</strong><span>Confirm your gate on the airport displays.</span></div><button class="text-button" data-view="flights">View loaded flight details ${icon('arrow')}</button></div></section>`:'';}
function changeNotice(){return context().changed?`<section class="travel-update gate-update" role="status" aria-label="Gate change update"><div class="update-icon">${icon('bell')}</div><div><div class="update-label">GATE UPDATE · NH 106</div><h2>Your departure gate is now 108A</h2><div class="gate-change"><span class="old-gate">Gate 105</span>${icon('arrow')}<strong>Gate 108A</strong><span class="meta">Terminal 3</span></div><p>Your departure remains at 18:00 JST. Your route now leads to the new gate.</p><button class="secondary" data-action="start-route">View route to Gate 108A ${icon('arrow')}</button></div></section>`:'';}

function connectionRisk(c=context()){
 if(c.offline||c.transfer||!c.routeKnown)return null;
 const margin=c.available-c.walk;
 if(margin<=0)return {level:'critical',title:'You may miss boarding',detail:'Contact the airline now to confirm boarding and discuss rebooking options.',action:'airline-assistance',label:'Boarding & rebooking help'};
 if(margin<5)return {level:'late',title:'You may be late',detail:`Go directly to Gate ${c.gate}. Ask airline staff for help if needed.`,action:'direct-route',label:'View direct gate route'};
 if(margin<=10)return {level:'tight',title:'Time is tight',detail:`Head to Gate ${c.gate} and leave optional stops for later.`,action:'direct-route',label:'View direct gate route'};
 const plan=J.estimate(journeyState);
 if(journeyState.stops.length&&plan.known&&plan.arrival>plan.deadline)return {level:'plan',title:'Review your plan',detail:`Your current stops put you at Gate ${c.gate} at ${clockTime(plan.arrival)}, after your ${clockTime(plan.deadline)} arrival target. Review a change before continuing.`,action:'review-plan',label:'Review my plan'};
 if(journeyState.stops.length&&!plan.known)return {level:'plan',title:'Check your plan before continuing',detail:'Some route or wait information is unavailable. Check the missing details before visiting your stops.',action:'review-plan',label:'Review my plan'};
 return null;
}
function riskNotice(r){return `<section class="travel-update ${r.level==='critical'?'risk-critical':'risk-caution'}" role="alert" aria-label="Boarding timing warning"><div class="update-icon">${icon('clock')}</div><div><div class="update-label">${r.level==='critical'?'BOARDING AT RISK':'CHECK YOUR TIMING'}</div><h2>${r.title}</h2><p>${r.detail}</p><button class="secondary" data-action="${r.action}">${r.label} ${icon('arrow')}</button>${r.level==='critical'?'<button class="text-button" data-action="direct-route">View direct gate route '+icon('arrow')+'</button>':''}</div></section>`;}
function globalUpdate(){const c=context(),risk=connectionRisk(c);let message='';
 if(!c.transfer&&!c.routeKnown)message=gateConfirmation();
 else if(c.offline)message=offlineNotice();
 else if(c.changed)message=changeNotice()+(risk&&state.view!=='journey'?riskNotice(risk):'');
 else if(risk&&state.view!=='journey')message=riskNotice(risk);
 else if(c.urgent&&state.view!=='journey')message=`<section class="travel-update return-update" role="status" aria-label="Return reminder"><div class="update-icon">${icon('clock')}</div><div><div class="update-label">TIME TO RETURN · GATE ${c.gate}</div><h2>Aim to reach your gate in ${c.available} minutes</h2><p>Head directly to Gate ${c.gate}. Leave optional stops for later.</p><button class="secondary" data-action="direct-route">${state.view==='guide'?'Continue direct gate route':'View direct route to your gate'} ${icon('arrow')}</button></div></section>`;
 return message?`<div class="global-update">${message}</div>`:'';
}
function gateConfirmation(){return `<section class="notice amber" role="status"><div><strong>Confirm your departure gate</strong><p>Last known gate: ${esc(String(context().gate))}. This information may be out of date. Check airport displays or ask airline staff before following a route.</p></div></section>`;}
function hero(){const c=context(),r=connectionRisk(c),critical=r?.level==='critical';if(!c.transfer&&!c.routeKnown)return `<section class="card pad" aria-label="Your next action"><h2>Confirm your departure gate</h2><p class="sub">Last known gate: ${esc(String(c.gate))}. Check airport displays or ask airline staff before following a route.</p></section>`;return `<section class="card hero ${c.urgent?'alert':''} ${r&&!critical?'caution':''}" aria-label="Your next action" ${r?'role="alert"':''}><div class="row start"><div class="eyebrow">YOUR NEXT STEP</div>${pill(r?r.level==='plan'?'REVIEW YOUR PLAN':'BOARDING AT RISK':c.urgent?'TIME TO RETURN':c.transfer?'TRANSFER REQUIRED':'CONNECTION OVERVIEW',critical?'red':r||c.transfer?'amber':'',c.urgent?'clock':c.transfer?'transfer':'check')}</div><h2>${r?r.title:c.urgent?`Head to Gate ${c.gate} now`:c.transfer?'Transfer to Tokyo Narita':`Time before Gate ${c.gate}`}</h2><p>${r?r.detail:c.urgent?`Head directly to Gate ${c.gate} and leave optional stops for later.`:c.transfer?'You arrive at Haneda (HND) and depart from Narita (NRT). Check baggage and entry steps before starting the airport transfer.':'Review your gate details and route before choosing a nearby stop.'}</p><button class="primary hero-action" data-action="${r?r.action:c.transfer?'transfer-steps':c.urgent?'direct-route':'start-route'}">${icon(critical?'info':c.transfer?'transfer':'walk')}${r?r.label:c.transfer?'Review transfer steps':c.urgent?'Start route to your gate':`Route to Gate ${c.gate}`}${icon('arrow')}</button>${critical?'<button class="text-button" data-action="direct-route">View direct gate route '+icon('arrow')+'</button>':''}<div class="hero-grid"><div><small>${c.transfer?'Onward airport':'Departure gate'}</small><strong>${c.transfer?'NRT · T1':`${c.gate} · T3`}</strong></div><div><small>Until gate-arrival target</small><strong>${time(c.available)}</strong></div><div><small>Departure · JST</small><strong>${c.transfer?'21:00':'18:00'}</strong></div></div></section>`;}
function rail(){const c=context();return `<aside class="trip-rail stack" aria-label="Trip overview"><div class="card"><div class="journey-rail"><div class="row"><span class="eyebrow" style="margin:0">YOUR ITINERARY</span>${icon('flights')}</div><div class="flight-path"><div class="airport"><div class="airport-code">BKK</div><small>Bangkok</small></div><div class="connection">${icon('plane')}</div><div class="airport end"><div class="airport-code">LAX</div><small>Los Angeles</small></div></div><div class="timeline"><div class="timeline-item"><div><strong>Bangkok</strong><small>TG 660 · Departure</small></div><div class="time-right">05:15<br>ICT · 15 Oct</div></div><div class="timeline-item current"><div><strong>Tokyo Haneda</strong><small>${c.transfer?'Arrival · Change airports':'Connection · Terminal 3'}</small></div><div class="time-right">11:15<br>JST · 15 Oct</div></div>${c.transfer?'<div class="timeline-item current"><div><strong>Tokyo Narita</strong><small>Onward airport · Terminal 1</small></div><div class="time-right">21:00<br>JST · 15 Oct</div></div>':''}<div class="timeline-item"><div><strong>Los Angeles</strong><small>${c.flight} · Onward flight</small></div><div class="time-right">${c.transfer?'15:00':'11:45'}<br>PDT · 15 Oct</div></div></div><button class="text-button" data-view="flights">View flight details ${icon('arrow')}</button></div><div class="rail-footer">All times are <strong>local to each airport.</strong><br>Thursday, 15 October 2026</div></div><div class="notice">${icon('shield')}<div><strong>Check your next departure.</strong><p>Review your flight details and route. Confirm the latest gate and boarding time on airport displays.</p></div></div></aside>`;}
function loungeArt(){return `<div class="plan-visual" aria-hidden="true"><svg viewBox="0 0 500 120" preserveAspectRatio="xMidYMid slice"><rect width="500" height="120" fill="#e6eee4"/><path d="M0 97h500M65 0v97M175 0v97M285 0v97M395 0v97" stroke="#c6d7c9"/><path d="m280 30 50 9 85-12-74 23-29 29-12-5 14-26-42-8z" fill="#b4c9b9"/><rect x="105" y="72" width="49" height="24" rx="9" fill="#78988b"/><rect x="165" y="72" width="49" height="24" rx="9" fill="#78988b"/><path d="M112 96v17m35-17v17m25-17v17m35-17v17" stroke="#547568" stroke-width="3"/><path d="M384 96V51m0 30q-24-25-12-40 24 10 12 40m0-6q25-26 31-9-7 21-31 9" fill="#9ab7a0" stroke="#89a995"/><rect x="371" y="96" width="27" height="18" rx="3" fill="#b6c5ac"/></svg><span class="visual-caption">A moment between flights</span></div>`;}
function clockTime(minutes){if(!Number.isFinite(minutes))return 'To confirm';return new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tokyo'}).format(new Date(Date.UTC(2026,10,7,7,30)+minutes*60000));}
function planCard(){const estimate=J.estimate(journeyState);displayedRecommendations=J.recommendations(journeyState);const r=displayedRecommendations[0];return `<section class="card pad" id="my-plan" tabindex="-1" aria-label="My plan"><div class="section-head"><h2>My plan</h2><button class="text-button" data-view="explore">Add a stop</button></div>${journeyState.stops.length?journeyState.stops.map((stop,i)=>`<article class="directory-row"><div class="row"><div><h3>${i+1}. ${esc(J.catalog[stop.facilityId].name)}</h3><p class="meta">${stop.status==='completed'?'Completed':`${stop.minutes} min visit`}</p></div><button class="text-button" data-remove="${stop.id}" aria-label="Remove ${esc(J.catalog[stop.facilityId].name)}">Remove</button></div><button class="text-button" data-move="${stop.id}" data-offset="-1" ${i===0?'disabled':''}>Move earlier</button><button class="text-button" data-move="${stop.id}" style="margin-left:16px" data-offset="1" ${i===journeyState.stops.length-1?'disabled':''}>Move later</button></article>`).join(''):(context().routeKnown?'<p>No stops added yet. Your route goes directly to the gate.</p>':'<p>No stops added yet. Confirm your gate before following a route.</p>')}<p class="meta">${estimate.known?`Gate ${esc(journeyState.gate)} arrival ${clockTime(estimate.arrival)} · ${estimate.travel} min travel`:'Some route information is unavailable. Check current waits and your gate-arrival target before visiting.'}<br>Aim to reach your gate by ${clockTime(journeyState.deadline)}.</p>${r?`<div class="notice amber"><div><strong>${r.reason==='rain'?'Rain may affect your outdoor stop.':'Your plan runs past your gate-arrival target.'}</strong><p>Remove ${esc(J.catalog[journeyState.stops.find(x=>x.id===r.stopId).facilityId].name)} to arrive at ${clockTime(r.after)} (${r.saved} min earlier).${r.fits?'':' This change alone does not meet your gate-arrival target. Review the remaining stops and current boarding instructions.'}</p><button class="secondary" data-apply="${r.id}">Apply change</button></div></div>`:''}${timingSummary()}${journeyState.undo&&journeyState.undo.revision===journeyState.revision?'<button class="text-button" data-action="undo-plan">Undo plan change</button>':''}</section>`;}
function recommendedCard(){const c=context(),critical=connectionRisk(c)?.level==='critical',chosen=facilities.find(f=>journeyState.stops.some(stop=>stop.facilityId===f.id&&stop.status!=='completed'));return `<section class="card">${loungeArt()}<div class="plan-content"><div class="row"><span class="eyebrow" style="margin:0">${chosen?'YOUR SELECTED STOP':'TIME BETWEEN FLIGHTS'}</span>${pill(c.urgent?'RETURN FIRST':chosen?'PLAN SELECTED':'AIRSIDE',c.urgent?'amber':'',chosen?'check':'')}</div><h3>${critical?'Check boarding with your airline':c.urgent?'Your gate comes first':chosen?esc(chosen.name):'Stay close. Make yourself comfortable.'}</h3><p>${critical?'Contact the airline for current boarding instructions and rebooking options.':c.urgent?'Head to your gate now. Follow the route guide for directions.':chosen?esc(chosen.desc):'Rest, grab a coffee, or find a place to work within the departure area.'}</p><div class="plan-facts"><span>${icon('gate')}Terminal 3 · Airside</span></div><div class="plan-actions"><button class="secondary" data-${critical?'action="airline-assistance"':c.urgent?'action="direct-route"':'view="explore"'}>${critical?'Get airline help':c.urgent?'Go to route':chosen?'Change plan':'Explore nearby'}</button><button class="text-button" data-action="why">Why stay airside? ${icon('arrow')}</button></div></div></section>`;}
function journey(){const c=context();return `<div class="layout"><div class="stack">${hero()}${planCard()}${c.transfer?transferCard():c.urgent?'':recommendedCard()}<div class="quick-links"><button class="quick-link" data-view="map">${icon('map')}<strong>Get your bearings</strong><span>Terminal map & step-by-step route</span></button><button class="quick-link" data-action="bags">${icon('bag')}<strong>Baggage, made clearer</strong><span>Check the next step for your bags</span></button></div></div>${rail()}</div>`;}
function flightCard(inbound){const c=context();return `<article class="card pad"><div class="row"><span class="eyebrow" style="margin:0">${inbound?'FLIGHT 1 OF 2 · THAI AIRWAYS':'FLIGHT 2 OF 2 · ANA'}</span>${pill(inbound?'Arrived':c.urgent?'Boarding soon':'Scheduled',c.urgent&&!inbound?'amber':'',inbound?'check':'')}</div><div class="row" style="margin-top:10px"><h2>${inbound?'TG 660':c.flight}</h2><span class="meta">15 October 2026</span></div><div class="flight-path"><div class="airport"><div class="airport-code">${inbound?'BKK':c.airport}</div><div style="font-size:21px;margin-top:6px">${inbound?'05:15':c.transfer?'21:00':'18:00'}</div><small>${inbound?'Bangkok · ICT':c.transfer?'Tokyo Narita · JST':'Tokyo Haneda · JST'}</small></div><div class="connection">${icon('plane')}</div><div class="airport end"><div class="airport-code">${inbound?'HND':'LAX'}</div><div style="font-size:21px;margin-top:6px">${inbound?'11:15':c.transfer?'15:00':'11:45'}</div><small>${inbound?'Tokyo Haneda · JST':'Los Angeles · PDT'}</small></div></div><div class="detail-grid"><div><span>${inbound?'Arrival terminal':'Departure terminal'}</span>${inbound?'3':c.transfer?'1':'3'}</div><div><span>${inbound?'Arrival gate':!c.routeKnown&&!c.transfer?'Last known gate · confirm':'Departure gate'}</span>${inbound?'146':c.transfer?'Confirm at airport':c.gate}</div><div><span>${inbound?'Flight status':'Gate-arrival target · JST'}</span>${inbound?'Arrived':c.transfer?'20:20':clockTime(journeyState.deadline)}</div></div>${!inbound?'<button class="text-button" data-action="flight-info">Boarding details '+icon('info')+'</button>':''}</article>`;}
function flights(){const c=context();return `<div class="layout"><div class="stack">${flightCard(true)}${c.transfer?'<div class="notice amber">'+icon('transfer')+'<div><strong>Airport change required: HND → NRT</strong><p>Your ticket continues from Tokyo Narita. Review the transfer sequence before making other plans.</p><button class="text-button" data-action="transfer-steps">Review transfer steps '+icon('arrow')+'</button></div></div>':''}${flightCard(false)}<div class="notice">${icon('info')}<div><strong>Every time is local.</strong><p>Your arrival time in Los Angeles may look earlier than your departure time in Tokyo because of the time-zone change.</p></div></div></div>${rail()}</div>`;}
function transferCard(){return `<section class="card pad"><div class="section-head"><h2>Your transfer checklist</h2>${icon('transfer')}</div><ol class="task-list"><li>${icon('bag')}<div><strong>Confirm baggage handling</strong><small>Ask whether you need to collect and recheck your bags for the airport change.</small></div></li><li>${icon('shield')}<div><strong>Verify entry requirements</strong><small>Airport transfers may involve entering the country. Verify your itinerary with the airline and official authorities.</small></div></li><li>${icon('map')}<div><strong>Confirm current transport</strong><small>Check operating hours, travel time, fare, and the onward check-in deadline.</small></div></li></ol><button class="secondary full" data-action="transfer-steps">Review what to confirm ${icon('arrow')}</button></section>`;}
function explore(){const c=context();return `<div class="layout"><div class="stack">${c.transfer?'<div class="notice amber">'+icon('transfer')+'<div><strong>Airport transfer comes first.</strong><p>Review your transfer steps before considering an optional stop.</p></div></div>':''}<div><div class="view-tabs" role="group" aria-label="Access area">${[['airside','Airside'],['landside','Landside'],['city','City & transfer']].map(([v,n])=>`<button data-zone="${v}" class="${state.zone===v?'active':''}" aria-pressed="${state.zone===v}">${n}</button>`).join('')}</div>${state.zone==='airside'?`<div class="row" style="margin-bottom:17px"><div><h2 style="font-size:19px">Places near your gate</h2><p class="meta" style="margin-top:5px">Terminal 3 · Inside security</p></div><button class="text-button" data-action="why">${icon('info')}Why airside?</button></div><div class="filters" role="group" aria-label="Filter nearby activities">${[['all','All'],['rest','Rest'],['food','Food & drink'],['work','Work']].map(([v,n])=>`<button class="filter ${state.filter===v?'active':''}" data-filter="${v}" aria-pressed="${state.filter===v}">${n}</button>`).join('')}</div><div class="plan-grid">${facilities.filter(f=>state.filter==='all'||f.category===state.filter).map(f=>`<article class="facility ${selected(f.id)?'selected-border':''}"><div class="row"><div class="facility-icon">${icon(f.symbol)}</div>${pill(selected(f.id)?'Selected':'Nearby',selected(f.id)?'':'neutral',selected(f.id)?'check':'')}</div><h3>${f.id==='rest'&&!c.routeKnown?'Quiet time near your gate':f.id==='rest'&&c.changed?'Quiet time near Gate 108A':esc(f.name)}</h3><p>${esc(f.desc)}</p><div class="meta">${esc(f.zone)}</div><button class="${selected(f.id)?'secondary':'primary'} full" data-plan="${f.id}" ${c.urgent||c.transfer?'disabled':''}>${selected(f.id)?'Plan selected':'Add to my plan'}${icon(selected(f.id)?'check':'arrow')}</button></article>`).join('')}</div>`:state.zone==='landside'?`<section class="card pad"><div class="empty">${icon('shield')}<h2>Check access before leaving airside</h2><p>Check entry permission, baggage handling, and your return route before heading landside. Leave time to pass through security again.</p>${pill('REQUIRES CONFIRMATION','amber')}<div><button class="text-button" data-action="entry">What should I confirm? ${icon('arrow')}</button></div></div></section>`:transferCard()}</div>${directoryCard()}${journeyState.stops.length?'<div class="notice">'+icon('check')+'<div><strong>Added to your plan.</strong><p>It appears on your Journey screen. Gate changes and return alerts still take priority.</p><button class="text-button" data-view="journey">Back to your journey '+icon('arrow')+'</button></div></div>':''}</div>${rail()}</div>`;}
function routeStops(){return state.routeDirect?[]:journeyState.stops.filter(x=>x.status!=='completed');}
function routeSteps(){const c=context();return [{title:journeyState.stops.some(x=>x.status==='completed')?'Continue from your last completed stop':'Start at International Gates',desc:'Terminal 3',direction:'up'},...routeStops().map(stop=>({title:J.catalog[stop.facilityId].name,desc:`Stop in your plan · ${stop.minutes} min visit`,direction:'up',stopId:stop.id})),{title:state.accessible?'Follow the step-free route to your gate':`Follow signs to Gate ${c.gate}`,desc:'Confirm the route with current airport signs',direction:'right'},{title:`Arrive at Gate ${c.gate}`,desc:'Check the airport display and wait for boarding instructions',direction:'check'}];}
function mapGraphic(){const stops=routeStops();const points=[{name:'Current position'},...stops.map(s=>({name:J.catalog[s.facilityId].name})),{name:`Gate ${context().gate}`}];const height=Math.max(230,points.length*65+40);return `<svg class="route-map" viewBox="0 0 600 ${height}" role="img" aria-label="${state.routeDirect?'Direct route overview to your gate':'Ordered route overview through your selected stops'}"><path d="M45 40V${40+(points.length-1)*65}" stroke="#137971" stroke-width="5" fill="none"/>${points.map((p,i)=>`<circle cx="45" cy="${40+i*65}" r="8" fill="#126b67"/><text x="70" y="${45+i*65}">${esc(p.name)}</text>`).join('')}</svg>`;}
function map(){const c=context();if(!c.transfer&&!c.routeKnown)return `<div class="layout"><div class="stack">${gateConfirmation()}</div>${rail()}</div>`;if(c.transfer)return `<div class="layout"><div class="stack">${hero()}<div class="notice amber">${icon('info')}<div><strong>This is a transfer between airports.</strong><p>Haneda and Narita are separate airports. Confirm current ground transport and entry requirements before leaving the terminal.</p></div></div>${transferCard()}</div>${rail()}</div>`;return `<div class="layout"><div class="stack"><section class="card"><div style="padding:20px 21px" class="row"><div><h2 style="font-size:18px">Route to Gate ${c.gate}</h2><p class="meta" style="margin-top:4px">${state.accessible?'Step-free preference · ':''}Terminal 3</p></div>${pill('TERMINAL 3','neutral')}</div>${state.routeDirect?'<p class="meta" style="padding:0 21px">Direct route to your gate. Your saved stops remain in My plan.</p>':''}${mapGraphic()}<ol class="task-list" aria-label="Selected route stops" style="padding:20px">${routeStops().map(stop=>`<li>${esc(J.catalog[stop.facilityId].name)}</li>`).join('')}<li>Gate ${esc(c.gate)}</li></ol><div class="map-legend"><span><i class="map-dot"></i>Your route</span><span><i class="map-dot pale"></i>Other gate</span><span>Level 3 · Departures</span></div></section><section class="card pad"><div class="section-head"><h2>Your route, step by step</h2>${icon(state.accessible?'accessible':'walk')}</div>${routeSteps().map((s,i)=>`<div class="route-step ${i===state.routeStep?'active':''}"><span class="step-number">${i+1}</span><div><strong>${s.title}</strong><p>${s.desc}</p></div></div>`).join('')}<button class="primary full" style="margin-top:20px" data-action="start-route">${icon('guide')}${state.routeActive?'Continue route guide':'Start route guide'} ${icon('arrow')}</button><button class="text-button" data-action="map-info">About this map ${icon('info')}</button></section></div>${rail()}</div>`;}
function guide(){const c=context();if(!c.transfer&&!c.routeKnown)return `<div class="layout"><div class="stack">${gateConfirmation()}</div>${rail()}</div>`;if(c.transfer)return map();const steps=routeSteps(),step=steps[Math.min(state.routeStep,steps.length-1)];return `<div class="layout"><div class="stack"><section class="card pad"><div class="row"><div><div class="eyebrow">TO YOUR ONWARD FLIGHT</div><h2>Gate ${c.gate} · Terminal 3</h2></div>${pill(state.routeStep===steps.length-1?'FINAL STEP':'TO YOUR GATE',state.routeStep===steps.length-1?'':'neutral',state.routeStep===steps.length-1?'check':'')}</div><div class="guide-stage">${icon(step.direction)}<div class="eyebrow" style="margin-top:18px">STEP ${state.routeStep+1} OF ${steps.length}</div><h2>${step.title}</h2><p>${step.desc}</p></div><div class="notice">${icon('info')}<div><strong>Follow the departures signs.</strong><p>Check each direction as you reach the next landmark. You can review the full route on the terminal map.</p></div></div><div class="progress-track" role="progressbar" aria-label="Route progress" aria-valuenow="${state.routeStep+1}" aria-valuemin="1" aria-valuemax="${steps.length}"><div style="width:${(state.routeStep+1)/steps.length*100}%"></div></div><div class="row" style="margin-top:20px"><button class="secondary" data-action="previous-step" ${state.routeStep===0?'disabled':''}>Previous</button><button class="primary" data-action="${state.routeStep===steps.length-1?'finish-route':step.stopId?'complete-stop':'next-step'}">${state.routeStep===steps.length-1?'Back to journey':step.stopId?'Finish stop':'Next step'}${icon(state.routeStep===steps.length-1?'check':'arrow')}</button></div><button class="text-button" data-view="map">${icon('map')}View terminal map</button></section><div class="notice">${icon('walk')}<div><strong>Keep your attention on your surroundings.</strong><p>Look up while walking and follow the departures signs.</p></div></div></div>${rail()}</div>`;}
function settings(){return `<div class="layout"><div class="stack"><section class="card pad"><div class="section-head"><h2>Make the route work for you</h2>${icon('walk')}</div><form id="preferences"><p class="meta">Walking times use an average estimate until airport walking history is available.</p><label class="check-row"><input type="checkbox" name="accessible" ${state.accessible?'checked':''}>Prefer a step-free route</label><div class="form-field"><label for="bags">Baggage for this trip</label><select id="bags" name="bags"><option value="through" ${state.bags==='through'?'selected':''}>Tagged to final destination</option><option value="collect" ${state.bags==='collect'?'selected':''}>Collect and recheck</option><option value="unknown" ${state.bags==='unknown'?'selected':''}>I need to confirm</option></select></div><label class="check-row"><input type="checkbox" name="largeText" ${state.largeText?'checked':''}>Use larger text</label><button class="primary full" type="submit">Save preferences ${icon('check')}</button></form></section><section class="card pad"><div class="section-head"><h2>A lighter footprint</h2>${icon('shield')}</div><p class="meta">Your preferences stay in this session. Your route needs and baggage choices help keep the next step relevant to you.</p><button class="text-button" data-action="reset">Reset this session ${icon('refresh')}</button></section></div>${rail()}</div>`;}
function openDialog(title,body){const d=document.querySelector('#dialog');d.innerHTML=`<button class="icon-button close-dialog" data-close aria-label="Close dialog">${icon('close')}</button><h2 id="dialog-title">${title}</h2>${body}`;d.showModal();}
function whyDialog(){openDialog('Why stay airside?',`<p>A short stop inside the departure area avoids adding border entry, a return security queue, and city transport to your connection.</p><ul><li>Review your onward gate and walking route before choosing a stop.</li><li>Landside and city plans remain unresolved until entry, baggage, queue, and return details are confirmed.</li><li>Adding a stop keeps the gate-change and return messages shown for this trip.</li></ul><div class="notice">${icon('info')}<div>Check opening hours and access restrictions before choosing a stop.</div></div><button class="primary full" data-close>Got it ${icon('check')}</button>`);}
function bagsDialog(){const transfer=context().transfer;const copy=state.bags==='collect'?'You’ve selected collect and recheck. Confirm the baggage belt, customs steps, recheck location, and check-in deadline with your airline.':state.bags==='unknown'?'Ask your airline whether your bag is checked through to the final destination or whether you must collect and recheck it.':'You’ve indicated that your bag is tagged to the final destination. Confirm with your airline whether this itinerary still requires collection at the connection.';openDialog('Your next baggage step',`<p>${copy}</p>${transfer?'<div class="notice amber">'+icon('transfer')+'<div><strong>Your itinerary changes airports.</strong><p>Confirm how your bags move from Haneda to Narita before starting the transfer.</p></div></div>':''}<p>Read the baggage tag and follow the airline’s instructions for your actual ticket.</p><button class="secondary full" data-view="settings" data-close>Update baggage preference</button>`);}
function transferDialog(){openDialog('HND → NRT: confirm, then travel',`<p>Your onward flight departs Narita Terminal 1 at 21:00 JST. Confirm baggage and entry steps before choosing transport.</p><ol class="task-list"><li>${icon('bag')}<div><strong>Ask about baggage</strong><small>Confirm collection and recheck requirements for this ticket.</small></div></li><li>${icon('shield')}<div><strong>Verify entry and documents</strong><small>Use official guidance and your airline for your nationality and itinerary.</small></div></li><li>${icon('transfer')}<div><strong>Check transport and deadlines</strong><small>Confirm service, current travel time, check-in cutoff, and time needed on arrival.</small></div></li></ol>${pill('CHECK BEFORE DEPARTURE','amber')}<button class="primary full" data-close>Close checklist ${icon('check')}</button>`);}
function entryDialog(){openDialog('Before leaving the departure area',`<p>Confirm entry permission for your documents and itinerary with official authorities and your airline. A valid onward ticket alone does not establish entry eligibility.</p><ul><li>Whether baggage must be collected or rechecked.</li><li>Terminal access rules and the security process for returning.</li><li>Current transport, queues, and your flight’s check-in and gate-close deadlines.</li></ul><p>Keep these details with your travel documents so they’re easy to check before you leave airside.</p><button class="primary full" data-close>Understood</button>`);}
function aboutDialog(){openDialog('A calmer connection, with AirBorder',`<p>Review your connection, explore nearby stops, and plan your route to the gate.</p><ul><li><strong>Journey</strong> brings your gate, deadline, and return route together.</li><li><strong>Layover & transit</strong> helps you find a stop that fits your connection.</li><li><strong>Preferences</strong> lets you choose a step-free route.</li></ul><button class="primary full" data-close>Back to my trip ${icon('arrow')}</button>`);}

function action(name){switch(name){
 case 'review-plan':if(state.view!=='journey')navigate('journey');document.querySelector('#my-plan')?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#my-plan')?.focus({preventScroll:true});break;
 case 'start-route':if(!context().routeKnown&&!context().transfer){navigate('guide');break;}if(context().transfer){transferDialog();break;}if(!state.routeActive){state.routeStep=0;state.routeDirect=false;}state.routeActive=true;navigate('guide');break;
 case 'direct-route':if(!context().routeKnown&&!context().transfer){navigate('guide');break;}if(context().transfer){transferDialog();break;}if(!state.routeActive||!state.routeDirect)state.routeStep=0;state.routeDirect=true;state.routeActive=true;navigate('guide');break;
 case 'complete-stop':{const step=routeSteps()[state.routeStep];if(step?.stopId&&J.complete(journeyState,step.stopId)){render();document.querySelector('#announcement').textContent='Stop completed. '+routeSteps()[state.routeStep].title;}break;}
 case 'next-step':state.routeStep=Math.min(routeSteps().length-1,state.routeStep+1);render();document.querySelector('#announcement').textContent=routeSteps()[state.routeStep].title;break;
 case 'previous-step':state.routeStep=Math.max(0,state.routeStep-1);render();break;
 case 'finish-route':state.routeActive=false;state.routeDirect=false;state.routeStep=0;navigate('journey');toast(`Route guide complete. Confirm Gate ${context().gate} on airport signs.`);break;
 case 'airline-assistance':openDialog('Check boarding and rebooking',`<p><strong>${context().flight} · ${context().routeKnown?'Gate':'Last known gate (confirm)'} ${context().gate} · Terminal 3</strong></p><p>Confirm the current boarding status with airline staff before making changes to your trip.</p><ol class="task-list"><li>${icon('gate')}<div><strong>Ask whether you can still board</strong><small>Contact the departure gate or the airline service desk for instructions.</small></div></li><li>${icon('flights')}<div><strong>Ask about the next available flight</strong><small>If boarding is no longer possible, review rebooking options with the airline or your booking provider.</small></div></li><li>${icon('bag')}<div><strong>Confirm bags and any costs</strong><small>Ask how checked baggage will be handled and review fare differences or fees before accepting a change.</small></div></li></ol><button class="secondary full" data-view="flights" data-close>View flight details ${icon('arrow')}</button>`);break;
 case 'why':whyDialog();break;
 case 'refresh-directory':loadDirectory();break;
 case 'bags':bagsDialog();break;
 case 'entry':entryDialog();break;
 case 'transfer-steps':transferDialog();break;
 case 'about':aboutDialog();break;
 case 'profile':openDialog('Your travel profile',`<div class="row"><div class="avatar" style="width:54px;height:54px;font-size:18px">AV</div><div><h3>Your trip, your way</h3><p class="meta">Bangkok → Tokyo → Los Angeles</p></div></div><div class="divider"></div><div class="detail-grid"><div><span>Walking estimate</span>Average walking time</div><div><span>Route preference</span>${state.accessible?'Step-free':'Standard'}</div><div><span>Baggage</span>${state.bags==='through'?'Checked through':state.bags==='collect'?'Collect & recheck':'To confirm'}</div></div><button class="primary full" data-view="settings" data-close>Manage preferences ${icon('arrow')}</button>`);break;
 case 'map-info':openDialog('Finding your way through Terminal 3','<p>Your route connects International Gates, Departures Center, and your onward gate. Use the gate number on your boarding pass together with current airport signs.</p><p>For a step-free route, turn on “Prefer a step-free route” in Preferences.</p><button class="primary full" data-close>Back to the map</button>');break;
 case 'flight-info':openDialog('Your onward flight',`<p><strong>${context().flight} · ${context().transfer?'Tokyo Narita':'Tokyo Haneda'} → Los Angeles</strong></p><p>Departure: ${context().transfer?'21:00':'18:00'} JST · Terminal ${context().transfer?'1':'3'}<br>Aim to reach your gate: ${context().transfer?'20:20':clockTime(journeyState.deadline)} JST</p><p>Keep your boarding pass ready and check airport displays for the latest gate and boarding instructions.</p><button class="primary full" data-close>Back to flights</button>`);break;
 case 'more':openDialog('Your other tools',`<div class="dialog-options"><button class="secondary" data-view="guide" data-close>${icon('guide')}Route guide ${icon('arrow')}</button><button class="secondary" data-view="settings" data-close>${icon('settings')}Preferences ${icon('arrow')}</button><button class="secondary" data-action="about" data-close>${icon('info')}About AirBorder ${icon('arrow')}</button></div>`);break;
 case 'undo-plan':J.undo(journeyState);render();toast('Plan restored.');break;
 case 'reset':journeyState=J.create();Object.assign(state,{view:'journey',scenario:'connection',zone:'airside',filter:'all',plan:[],routeStep:0,routeActive:false,routeDirect:false,largeText:false,pace:'typical',minutesUntilClose:null,typicalWalk:12,accessible:false,bags:'through'});render();toast('Trip preferences reset');break;
 }}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=document.querySelector('#dialog');if(b.hasAttribute('data-close'))d.close();if(b.dataset.remove){J.remove(journeyState,b.dataset.remove);state.routeStep=0;render();toast('Stop removed.');return;}if(b.dataset.move){J.move(journeyState,b.dataset.move,Number(b.dataset.offset));state.routeStep=0;render();return;}if(b.dataset.apply){const r=displayedRecommendations.find(x=>x.id===b.dataset.apply);const ok=J.apply(journeyState,r);if(ok)state.routeStep=0;render();toast(ok?'Plan updated.':'Your plan changed. Review the updated suggestion.');return;}if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.action){action(b.dataset.action);return;}if(b.dataset.zone){state.zone=b.dataset.zone;render();return;}if(b.dataset.filter){state.filter=b.dataset.filter;render();return;}if(b.dataset.plan){if(context().urgent||context().transfer)return;J.add(journeyState,b.dataset.plan);render();toast('Added to your plan.');}});
document.addEventListener('change',e=>{if(e.target.id==='scenario'&&e.target.value!=='custom')resetScenario(e.target.value);});
document.addEventListener('submit',e=>{if(e.target.id!=='preferences')return;e.preventDefault();const f=new FormData(e.target);state.bags=f.get('bags');state.accessible=f.has('accessible');state.largeText=f.has('largeText');render();toast('Preferences updated');});
document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
function render(){if(!presenterMode){try{sessionStorage.setItem('airborder-journey-v1',JSON.stringify(journeyState));}catch{}}state.routeStep=Math.min(state.routeStep,routeSteps().length-1);document.querySelector('#app').innerHTML=shell(({journey,flights,explore,map,guide,settings}[state.view]||journey)());document.title=`${navNames[state.view]} · AirBorder`;scheduleTiming();}
render();

async function apiRequest(path,options={}){
 const response=await fetch(backend.base+path,{...options,credentials:'omit',signal:AbortSignal.timeout(8000)});
 if(!response.ok)throw new Error('service_unavailable');
 if(!(response.headers.get('content-type')||'').includes('application/json'))throw new Error('invalid_response');
 return response.json();
}
function timingInput(){const r=J.estimate(journeyState);if(!r.known)return null;return {availableMinutes:Math.max(0,journeyState.deadline-journeyState.now),walkingMinutes:r.travel,activityMinutes:r.dwell+r.queue,bufferMinutes:0};}
function timingKey(input){return JSON.stringify([journeyState.revision,journeyState.dataRevision,journeyState.now,input]);}
function scheduleTiming(){
 if(context().offline){backend.calculation=null;backend.calculationKey=null;return;}
 const input=timingInput();
 if(!input){backend.calculation=null;backend.calculationKey=null;return;}
 const key=timingKey(input);
 if(backend.calculationKey===key)return;
 backend.calculationKey=key;backend.calculation=null;
 apiRequest('/api/connection',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)}).then(result=>{
  if(backend.calculationKey!==key)return;
  if(typeof result.canFit!=='boolean'||!Number.isFinite(result.spareMinutes))throw new Error('invalid_response');
  backend.calculation=result;if(journeyState.stops.length)render();
 }).catch(()=>{if(backend.calculationKey===key)backend.calculation=null;});
}
function timingSummary(){
 const r=backend.calculation,input=timingInput();if(!journeyState.stops.length||!input||!r||backend.calculationKey!==timingKey(input)||r.canFit||context().urgent)return '';
 const detail=r.spareMinutes<0?`${Math.abs(r.spareMinutes)} minutes past your gate-arrival target`:'at your gate-arrival target';
 return `<div class="notice amber" role="status"><div><strong>Your plan needs more time</strong><p>Your plan is ${detail}. Check current waits and boarding instructions.</p></div></div>`;
}
function officialLink(value){try{const u=new URL(value);return u.protocol==='https:'&&['tokyo-haneda.com','www.shopping-sumitomo-rd.com'].includes(u.hostname)?u.href:null;}catch{return null;}}
function directoryCard(){
 if(backend.directoryStatus==='loading')return `<section class="card pad"><h2 style="font-size:18px">Airport directory</h2><p class="meta" style="margin-top:12px">Finding airport services…</p></section>`;
 if(backend.directoryStatus==='unavailable')return `<section class="card pad"><h2 style="font-size:18px">Airport directory</h2><p class="meta" style="margin-top:12px">Airport services are unavailable at the moment.</p><button class="text-button" data-action="refresh-directory">Try again ${icon('refresh')}</button></section>`;
 const zones={airside:'Airside',airportLandside:'Landside',nearbyLandside:'Landside · Nearby',mixed:'Access varies'};
 const list=backend.directory.filter(f=>state.zone==='airside'?['airside','mixed'].includes(f.accessZone):state.zone==='landside'?f.accessZone!=='airside':true);
 return `<section class="card pad" aria-label="Airport directory"><div class="section-head"><div><h2 style="font-size:18px">Airport directory</h2><p class="meta" style="margin-top:6px">Haneda services · Check access and hours before visiting</p></div>${icon('explore')}</div>${list.map(f=>`<article class="directory-row"><div class="row start"><div><h3>${esc(f.name)}</h3><p class="meta" style="margin-top:5px">${f.terminal?'Terminal '+esc(f.terminal)+' · ':''}${esc(zones[f.accessZone]||'Check access')}</p></div>${pill(zones[f.accessZone]||'Check access',f.accessZone==='airside'?'':'neutral')}</div><a class="text-button" href="${esc(officialLink(f.officialRecordURL))}" target="_blank" rel="noopener noreferrer">Access & opening hours ${icon('arrow')}</a></article>`).join('')||'<p class="meta">Check another area to see more services.</p>'}</section>`;
}
async function loadDirectory(){
 if(context().offline){backend.directoryStatus=backend.directory.length?'ready':'unavailable';render();return;}
 backend.directoryStatus='loading';render();
 try{const data=await apiRequest('/api/facilities?airport=HND');
  if(!Array.isArray(data.facilities))throw new Error('invalid_response');
  backend.directory=data.facilities.slice(0,50).filter(f=>typeof f.name==='string'&&f.name.length<200&&officialLink(f.officialRecordURL));
  backend.directoryStatus='ready';
 }catch{backend.directoryStatus='unavailable';}
 render();
}
loadDirectory();
